package com.himeros.billing;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;@Entity@Table(name="payments")class Payment{enum Status{PENDING,PAID,FAILED,REFUNDED}@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(nullable=false)private String plan;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(nullable=false)private String provider;@Column(name="provider_reference")private String providerReference;@Column(name="created_at",nullable=false)private Instant createdAt;protected Payment(){}Payment(UUID user,String plan,BigDecimal amount){id=UUID.randomUUID();userId=user;this.plan=plan;this.amount=amount;currency="BRL";status=Status.PAID;provider="fake-local";providerReference="fake_"+UUID.randomUUID();createdAt=Instant.now();}UUID id(){return id;}UUID user(){return userId;}String plan(){return plan;}BigDecimal amount(){return amount;}String currency(){return currency;}Status status(){return status;}Instant created(){return createdAt;}}
